cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__device__ __forceinline__ half sigmoid_half(half x) {
    // Sigmoid approximation for half precision
    return __hdiv(x, __hadd(__hone(), __hexp(__hneg(x))));
}

__global__ void swish_kernel(const half* input, half* output, int64_t total_elements) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        half x = input[idx];
        half sig_x = sigmoid_half(x);
        output[idx] = __hmul(x, sig_x);
    }
}

extern "C" {
    void launch_swish_kernel(const half* input, half* output, int64_t total_elements) {
        const int block_size = 256;
        const int grid_size = (total_elements + block_size - 1) / block_size;

        swish_kernel<<<grid_size, block_size>>>(input, output, total_elements);
        cudaDeviceSynchronize();
    }
}
"""

